def max_alternating_sum(arr):
    max_sum = float('-inf')
    current_sum = 0
    last_parity = None

    for num in arr:
        if num % 2 == 0:
            if last_parity is None or last_parity != 0:
                current_sum += num
                last_parity = 0
            else:
                max_sum = max(max_sum, current_sum)
                current_sum = num
                last_parity = 0
        else:
            if last_parity is None or last_parity != 1:
                current_sum += num
                last_parity = 1
            else:
                max_sum = max(max_sum, current_sum)
                current_sum = num
                last_parity = 1

    max_sum = max(max_sum, current_sum)
    return max_sum

