from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # Create a set of prime factors for each number
    prime_factors = [set() for _ in range(n)]
    for num in nums:
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                prime_factors[num].add(i)
                while num % i == 0:
                    num //= i

    # Check if all numbers have at least one prime factor
    for num in nums:
        if not prime_factors[num]:
            return False

    # Check if all pairs of indices can be connected
    for i in range(n):
        for j in range(i + 1, n):
            if gcd(nums[i], nums[j]) == 1:
                return False

    return True

def smallestString(s: str) -> str:
    s = list(s)
    n = len(s)

    for i in range(n):
        if s[i] == 'a':
            s[i] = 'z'
            continue

        for j in range(i, n):
            if s[j] == 'a':
                s[j] = 'z'
                continue

            if s[i] < s[j]:
                s[i], s[j] = s[j], s[i]
                break

    return ''.join(s)

