def longestEqualSubarray(nums, k):
    max_len = 0
    left = 0
    freq = {}

    for right in range(len(nums)):
        if nums[right] in freq:
            freq[nums[right]] += 1
        else:
            freq[nums[right]] = 1

        while (right - left + 1) - max(freq.values()) > k:
            freq[nums[left]] -= 1
            if freq[nums[left]] == 0:
                del freq[nums[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

def count_servers(n, logs, x, queries):
    # Create a dictionary to store the request times for each server
    server_requests = {}
    for server_id, time in logs:
        if server_id in server_requests:
            server_requests[server_id].append(time)
        else:
            server_requests[server_id] = [time]

    # Create a list to store the result for each query
    result = []

    # Process each query
    for query in queries:
        # Find the range of times for the query
        start_time = query - x
        end_time = query

        # Count the number of servers that received requests in the range
        count = 0
        for server_id, times in server_requests.items():
            # Check if there is any request in the range
            if any(time >= start_time and time <= end_time for time in times):
                count += 1

        # Append the result for the query
        result.append(count)

    return result

