def count_special_permutations(nums):
    MOD = 10**9 + 7
    count = 0
    for perm in permutations(nums):
        is_special = True
        for i in range(len(perm) - 1):
            if perm[i] % perm[i + 1] != 0 and perm[i + 1] % perm[i] != 0:
                is_special = False
                break
        if is_special:
            count += 1
            count %= MOD
    return count

