        sarr = sorted(subarr)
        imbalance = 0
        for i in range(len(sarr) - 1):
            if sarr[i+1] - sarr[i] > 1:
                imbalance += 1
        return imbalance

    total_imbalance = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n + 1):
            total_imbalance += imbalance_number(nums[i:j])
