def maxNonDecreasingSubarrayLength(nums1, nums2):
    n = len(nums1)
    dp = [[0]*n for _ in range(n)]

    for i in range(n):
        dp[i][0] = 1
        for j in range(i):
            if nums1[i] >= nums1[j] and nums1[i] >= nums2[j]:
                dp[i][0] = max(dp[i][0], dp[j][0] + 1)
            if nums2[i] >= nums1[j] and nums2[i] >= nums2[j]:
                dp[i][0] = max(dp[i][0], dp[j][0] + 1)

    for i in range(1, n):
        dp[i][1] = 1
