    max_length = 0
    for i in range(len(word)):
        for j in range(i, len(word)):
            if ''.join(word[i:j+1]) not in forbidden_set:
                max_length = max(max_length, j-i+1)
    return max_length

def permute_string(s: str) -> str:
    vowels = 'aeiouAEIOU'
    consonants = [c for c in s if c not in vowels]
    vowels.sort()
    result = list(s)
    vowel_index = 0

    for i in range(len(consonants)):
        result[i] = consonants[i]
        if vowel_index < len(vowels):
            result[i+1] = vowels[vowel_index]
            vowel_index += 1

    return ''.join(result)

def max_beauty(nums, k):
