def min_seconds_to_equalize(nums):
    n = len(nums)
    min_seconds = float('inf')

    for i in range(n):
        seconds = 0
        while True:
            nums[i] = min(nums[i], nums[(i - 1 + n) % n], nums[(i + 1) % n])
            seconds += 1
            if nums[i] == nums[i - 1]:
                break
        min_seconds = min(min_seconds, seconds)

    return min_seconds

def countSteppingNumbers(low: str, high: str) -> int:
    MOD = 10**9 + 7
    low = int(low)
    high = int(high)

    def dfs(pos, prev_digit, is_low):
        if pos == len(high):
            return 1
        count = 0
        for digit in range(10):
            if (pos == 0 and digit != 0) or (prev_digit != -1 and abs(digit - prev_digit) == 1):
                count = (count + dfs(pos + 1, digit, is_low)) % MOD
        return count

    return (dfs(0, -1, True) - dfs(0, -1, False)) % MOD

def countPairs(coordinates, k):
