def countWays(s, t, k):
    MOD = 10**9 + 7
    n = len(s)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for l in range(i):
                if s[i - 1] == t[j - 1]:
                    dp[i][j] = (dp[i][j] + dp[l][j - 1]) % MOD

    return dp[n][k]

def min_operations(nums, target):
    nums.sort(reverse=True)
    operations = 0
    while target > 0:
        if target >= nums[0]:
            target -= nums[0]
            nums.pop(0)
            nums.append(nums[0] / 2)
            operations += 1
        else:
            return -1
    return operations

def product_matrix(grid):
    MOD = 12345
    n, m = len(grid), len(grid[0])
    p = [[0]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            product = 1
            for k in range(n):
                for l in range(m):
                    if k != i and l != j:
                        product = (product * grid[k][l]) % MOD
            p[i][j] = product

    return p

def maxFunctionValue(receiver, k):
    n = len(receiver)
    # Initialize the binary lifting table
    binary_lift = [[0] * n for _ in range(n)]

    # Base case: 2^0 = 1
    for i in range(n):
        binary_lift[i][i] = receiver[i]

    # Fill the binary lifting table
    for j in range(1, n):
        for i in range(n):
            if binary_lift[i][j-1] != 0:
                binary_lift[i][j] = binary_lift[binary_lift[i][j-1]][j-1]

    # Function to calculate f(x)
    def f(x):
        total = x
        for j in range(k):
            total += binary_lift[x][j]
        return total

    # Find the maximum value of f(x)
    max_value = 0
    for x in range(n):
        max_value = max(max_value, f(x))

    return max_value

def minCost(s1, s2, x):
    n = len(s1)
    dp = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if s1[i - 1] == s2[j]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + x

    return dp[n][n] if dp[n][n] != float('inf') else -1

