def count_holeless_squares(H, W, N, holed_squares):
    # Create a grid to mark holed squares
    grid = [[False] * W for _ in range(H)]
    for a, b in holed_squares:
        grid[a-1][b-1] = True

    # Initialize the count of holeless squares
    holeless_count = 0

    # Iterate over all possible top-left corners of holeless squares
    for i in range(H):
        for j in range(W):
            # Check if the square (i, j) is holeless
            is_holeless = True
            for k in range(1, min(H-i, W-j)+1):
                for l in range(1, min(H-i+k, W-j+l)+1):
                    if grid[i+k-1][j+l-1]:
                        is_holeless = False
                        break
                if not is_holeless:
                    break
            if is_holeless:
                holeless_count += 1

    return holeless_count

def min_operations_to_one_diff(N, A):
    min_val = min(A)
    max_val = max(A)
    diff = max_val - min_val

    if diff <= 1:
        return 0

    operations = 0
    for i in range(N):
        if A[i] < min_val:
            operations += min_val - A[i]
        elif A[i] > max_val:
            operations += A[i] - max_val

    return operations

def solve_string_operations(N, S, Q, operations):
