def find_nth_repunit_sum(n):
    repunits = [1]
    for _ in range(1, n):
        repunits.append(repunits[-1] * 10 + 1)

    sums = set()
    for i in range(len(repunits) - 2):
        for j in range(i + 1, len(repunits) - 1):
            for k in range(j + 1, len(repunits)):
