def takahashi_adventure(N, events):
    from collections import defaultdict

    # Initialize potions and monsters
    potions = defaultdict(int)
    monsters = defaultdict(int)

    # Process events
    for t, x in events:
        if t == 1:
            # Find potion
            if x in potions:
                potions[x] += 1
            else:
                potions[x] = 1
        elif t == 2:
            # Encounter monster
            if potions[x] > 0:
                potions[x] -= 1
            else:
                return -1

    # Calculate K_min
    K_min = 0
    actions = []

    # Process potions in order of their types
    for potion_type in sorted(potions.keys()):
        if potion_type in potions:
            K_min += 1
            actions.append(1 if potion_type in potions else 0)

    return K_min, actions

