def determine_winner(N, cards):
    # Create a dictionary to store the cards by their front and back values
    cards_dict = {}
    for i in range(N):
        front, back = cards[i]
        if front not in cards_dict:
            cards_dict[front] = []
        cards_dict[front].append(i)
        if back not in cards_dict:
            cards_dict[back] = []
        cards_dict[back].append(i)

    # Function to check if a player can win given the current state of the cards
    def can_win(state):
        # If no cards are left, the player who just moved cannot win
        if not state:
            return False

        # Try all possible moves
        for front, back in state.items():
            for i in range(len(state[front])):
                for j in range(len(state[back])):
                    if state[front][i] == state[back][j]:
                        # Remove the cards from the state
                        new_state = {k: v[:] for k, v in state.items()}
                        new_state[front].pop(i)
                        new_state[back].pop(j)

                        # If the opponent cannot win from the new state, the current player wins
                        if not can_win(new_state):
                            return True
        return False

    # Start with the initial state of the cards
    initial_state = cards_dict

    # Determine the winner
    if can_win(initial_state):
        return "Takahashi"
    else:
        return "Aoki"

