def maxStrength(nums, k):
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - 1] + nums[i - 1] * (j - 1))

    return dp[n][k]

def minMoves(nums, k, maxChanges):
    n = len(nums)
    ones = [i for i, x in enumerate(nums) if x == 1]
    moves = 0

    # If there are already k ones, no moves are needed
    if len(ones) >= k:
        return 0

    # If maxChanges is enough to get k ones, use that
    if maxChanges >= k:
        return k

    # If maxChanges is not enough, use the ones that are not 0
    for i in range(n):
        if nums[i] == 1:
            ones.append(i)

    # Sort the ones in increasing order
    ones.sort()

    # Use the ones that are not 0 to fill the gaps
    for i in range(len(ones) - 1, k):
        if ones[i] == 0:
            moves += ones[i] - ones[i - 1] - 1
            ones[i] = 0

    # Use the ones that are 0 to fill the gaps
    for i in range(k, len(ones)):
        if ones[i] == 0:
            moves += ones[i] - ones[i - 1] - 1
            ones[i] = 0

    return moves

