def max_prime_distance(nums):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    max_distance = 0
    for i in range(len(nums)):
        if is_prime(nums[i]):
            max_distance = max(max_distance, i - nums.index(nums[i]))
    return max_distance

def min_sum_of_values(nums, andValues):
    n = len(nums)
    m = len(andValues)

    # Initialize the dp array
    dp = [[float('inf')] * (1 << 20) for _ in range(m + 1)]
    dp[0][0] = 0

    for i in range(1, m + 1):
        for mask in range(1 << 20):
            if mask & (1 << andValues[i - 1]):
                for j in range(i):
                    if mask & (1 << nums[j]):
                        dp[i][mask] = min(dp[i][mask], dp[j][mask ^ (1 << nums[j])] + andValues[i - 1])

    result = dp[m][(1 << 20) - 1]

    return result if result != float('inf') else -1

