def find_occurrences(nums, queries, x):
    answer = []
    for query in queries:
        count = 0
        for num in nums:
            if num == x:
                count += 1
                if count == query:
                    answer.append(nums.index(num))
                    break
        if count < query:
            answer.append(-1)
    return answer
